INSERT INTO wagtailcore_revision VALUES(16,'2026-04-19 05:48:51.095490',NULL,1,'{"pk": 6, "path": "00010002000100010001", "depth": 5, "numchild": 0, "translation_key": "6f01cbce-79e9-4074-8935-b843c6205e26", "locale": 1, "latest_revision": 16, "live": false, "has_unpublished_changes": true, "first_published_at": null, "last_published_at": null, "live_revision": null, "go_live_at": null, "expire_at": null, "expired": false, "locked": false, "locked_at": null, "locked_by": null, "title": "\u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u044c", "draft_title": "\u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u044c", "slug": "light-and-shadow", "content_type": 58, "url_path": "/portfolio/photo_studio/photo_portfolio/light-and-shadow/", "owner": 1, "seo_title": "", "show_in_menus": false, "search_description": "", "latest_revision_created_at": "2026-04-19T05:48:45.099Z", "alias_of": null, "date": "2026-02-10", "category_number": 2, "main_image": 51, "mini_description": "<p data-block-key=\"nh17k\">\u0421\u0442\u0430\u0440\u0438\u043d\u043d\u043e\u0435 \u0437\u0434\u0430\u043d\u0438\u0435, \u043e\u043a\u043d\u0430, \u0436\u0435\u043b\u0435\u0437\u043d\u044b\u0439 \u0431\u0430\u043b\u043a\u043e\u043d. \u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u0438 \u043d\u0430 \u0444\u0430\u0441\u0430\u0434\u0435.</p>", "title_image": 51, "short_description": "\u0421\u0442\u0430\u0440\u0438\u043d\u043d\u043e\u0435 \u0437\u0434\u0430\u043d\u0438\u0435, \u043e\u043a\u043d\u0430, \u0436\u0435\u043b\u0435\u0437\u043d\u044b\u0439 \u0431\u0430\u043b\u043a\u043e\u043d. \u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u0438 \u043d\u0430 \u0444\u0430\u0441\u0430\u0434\u0435.", "description": "<p data-block-key=\"insam\">\u0421\u0442\u0430\u0440\u0438\u043d\u043d\u043e\u0435 \u0437\u0434\u0430\u043d\u0438\u0435, \u0444\u0430\u0441\u0430\u0434 \u0441 \u043e\u043a\u043d\u0430\u043c\u0438 \u0438 \u0436\u0435\u043b\u0435\u0437\u043d\u044b\u043c \u0431\u0430\u043b\u043a\u043e\u043d\u043e\u043c. \u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u0438 \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u0441\u043b\u043e\u0436\u043d\u044b\u0439 \u0440\u0438\u0442\u043c: \u0431\u0430\u043b\u043a\u043e\u043d \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0438\u0447\u0443\u0434\u043b\u0438\u0432\u044b\u0435 \u0443\u0437\u043e\u0440\u044b \u043d\u0430 \u0441\u0442\u0435\u043d\u0443, \u043e\u043a\u043d\u0430 \u043e\u0442\u0440\u0430\u0436\u0430\u044e\u0442 \u043d\u0435\u0431\u043e \u0438 \u043e\u0431\u043b\u0430\u043a\u0430. \u041c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u0432 \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0447\u0430\u0441, \u043a\u043e\u0433\u0434\u0430 \u0441\u043e\u043b\u043d\u0446\u0435 \u0443\u0436\u0435 \u043d\u0438\u0437\u043a\u043e, \u0430 \u0442\u0435\u043d\u0438 \u0441\u0442\u0430\u043d\u043e\u0432\u044f\u0442\u0441\u044f \u0434\u043b\u0438\u043d\u043d\u044b\u043c\u0438 \u0438 \u0432\u044b\u0440\u0430\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438. \u0410\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430 \u043e\u0436\u0438\u0432\u0430\u0435\u0442 \u0432 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u0430\u0445 \u2014 \u0441\u0432\u0435\u0442\u043b\u043e\u0435 \u0438 \u0442\u0451\u043c\u043d\u043e\u0435, \u0441\u0442\u0430\u0440\u043e\u0435 \u0438 \u0432\u0435\u0447\u043d\u043e\u0435.</p>", "gallery": "[{\"type\": \"image\", \"value\": 53, \"id\": \"dad819d0-ecfc-4333-9f10-8cee73fd7eaa\"}, {\"type\": \"image\", \"value\": 52, \"id\": \"36ca527d-7701-4858-943a-0b81701d0caf\"}, {\"type\": \"image\", \"value\": 50, \"id\": \"cd86c30b-4824-4231-ad2d-def1239cc0d4\"}, {\"type\": \"image\", \"value\": 49, \"id\": \"4eba437d-e3eb-471c-8389-4471fee7aaee\"}]", "wagtail_admin_comments": []}','6',58,1,'Свет и тень');
INSERT INTO wagtailcore_revision VALUES(17,'2026-04-19 05:48:51.442637',NULL,1,'{"pk": 6, "path": "00010002000100010001", "depth": 5, "numchild": 0, "translation_key": "6f01cbce-79e9-4074-8935-b843c6205e26", "locale": 1, "latest_revision": 16, "live": false, "has_unpublished_changes": true, "first_published_at": null, "last_published_at": null, "live_revision": null, "go_live_at": null, "expire_at": null, "expired": false, "locked": false, "locked_at": null, "locked_by": null, "title": "\u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u044c", "draft_title": "\u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u044c", "slug": "light-and-shadow", "content_type": 58, "url_path": "/portfolio/photo_studio/photo_portfolio/light-and-shadow/", "owner": 1, "seo_title": "", "show_in_menus": false, "search_description": "", "latest_revision_created_at": "2026-04-19T05:48:51.095Z", "alias_of": null, "date": "2026-02-10", "category_number": 2, "main_image": 51, "mini_description": "<p data-block-key=\"nh17k\">\u0421\u0442\u0430\u0440\u0438\u043d\u043d\u043e\u0435 \u0437\u0434\u0430\u043d\u0438\u0435, \u043e\u043a\u043d\u0430, \u0436\u0435\u043b\u0435\u0437\u043d\u044b\u0439 \u0431\u0430\u043b\u043a\u043e\u043d. \u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u0438 \u043d\u0430 \u0444\u0430\u0441\u0430\u0434\u0435.</p>", "title_image": 51, "short_description": "\u0421\u0442\u0430\u0440\u0438\u043d\u043d\u043e\u0435 \u0437\u0434\u0430\u043d\u0438\u0435, \u043e\u043a\u043d\u0430, \u0436\u0435\u043b\u0435\u0437\u043d\u044b\u0439 \u0431\u0430\u043b\u043a\u043e\u043d. \u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u0438 \u043d\u0430 \u0444\u0430\u0441\u0430\u0434\u0435.", "description": "<p data-block-key=\"insam\">\u0421\u0442\u0430\u0440\u0438\u043d\u043d\u043e\u0435 \u0437\u0434\u0430\u043d\u0438\u0435, \u0444\u0430\u0441\u0430\u0434 \u0441 \u043e\u043a\u043d\u0430\u043c\u0438 \u0438 \u0436\u0435\u043b\u0435\u0437\u043d\u044b\u043c \u0431\u0430\u043b\u043a\u043e\u043d\u043e\u043c. \u0421\u0432\u0435\u0442 \u0438 \u0442\u0435\u043d\u0438 \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u0441\u043b\u043e\u0436\u043d\u044b\u0439 \u0440\u0438\u0442\u043c: \u0431\u0430\u043b\u043a\u043e\u043d \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0438\u0447\u0443\u0434\u043b\u0438\u0432\u044b\u0435 \u0443\u0437\u043e\u0440\u044b \u043d\u0430 \u0441\u0442\u0435\u043d\u0443, \u043e\u043a\u043d\u0430 \u043e\u0442\u0440\u0430\u0436\u0430\u044e\u0442 \u043d\u0435\u0431\u043e \u0438 \u043e\u0431\u043b\u0430\u043a\u0430. \u041c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u0432 \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0447\u0430\u0441, \u043a\u043e\u0433\u0434\u0430 \u0441\u043e\u043b\u043d\u0446\u0435 \u0443\u0436\u0435 \u043d\u0438\u0437\u043a\u043e, \u0430 \u0442\u0435\u043d\u0438 \u0441\u0442\u0430\u043d\u043e\u0432\u044f\u0442\u0441\u044f \u0434\u043b\u0438\u043d\u043d\u044b\u043c\u0438 \u0438 \u0432\u044b\u0440\u0430\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438. \u0410\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430 \u043e\u0436\u0438\u0432\u0430\u0435\u0442 \u0432 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u0430\u0445 \u2014 \u0441\u0432\u0435\u0442\u043b\u043e\u0435 \u0438 \u0442\u0451\u043c\u043d\u043e\u0435, \u0441\u0442\u0430\u0440\u043e\u0435 \u0438 \u0432\u0435\u0447\u043d\u043e\u0435.</p>", "gallery": "[{\"type\": \"image\", \"value\": 53, \"id\": \"dad819d0-ecfc-4333-9f10-8cee73fd7eaa\"}, {\"type\": \"image\", \"value\": 52, \"id\": \"36ca527d-7701-4858-943a-0b81701d0caf\"}, {\"type\": \"image\", \"value\": 50, \"id\": \"cd86c30b-4824-4231-ad2d-def1239cc0d4\"}, {\"type\": \"image\", \"value\": 49, \"id\": \"4eba437d-e3eb-471c-8389-4471fee7aaee\"}]", "wagtail_admin_comments": []}','6',58,1,'Свет и тень');
