INSERT INTO wagtailcore_revision VALUES(35,'2026-04-19 06:49:45.985617',NULL,1,'{"pk": 13, "path": "00010002000100010008", "depth": 5, "numchild": 0, "translation_key": "ca46db2a-0cf6-4657-99f7-674c8f944bff", "locale": 1, "latest_revision": null, "live": true, "has_unpublished_changes": false, "first_published_at": null, "last_published_at": null, "live_revision": null, "go_live_at": null, "expire_at": null, "expired": false, "locked": false, "locked_at": null, "locked_by": null, "title": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b. \u041d\u043e\u0447\u044c \u043c\u0430\u0441\u043e\u043a.", "draft_title": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b. \u041d\u043e\u0447\u044c \u043c\u0430\u0441\u043e\u043a.", "slug": "karnaval", "content_type": 58, "url_path": "/portfolio/photo_studio/portfolio_photo/karnaval/", "owner": 1, "seo_title": "", "show_in_menus": false, "search_description": "", "latest_revision_created_at": null, "alias_of": null, "date": "2026-02-01", "category_number": 3, "main_image": 82, "mini_description": "<p data-block-key=\"cxx16\">\u041f\u0430\u0440\u0430 \u0432 \u0441\u0432\u0435\u0442\u043b\u044b\u0445 \u043c\u0430\u0441\u043a\u0430\u0445 \u043d\u0430 \u0432\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u043e\u043c \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b\u0435, \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0441\u0432\u0435\u0442, \u043f\u043b\u043e\u0449\u0430\u0434\u044c \u0421\u0430\u043d-\u041c\u0430\u0440\u043a\u043e.</p>", "title_image": 81, "short_description": "\u0412\u0435\u043d\u0435\u0446\u0438\u044f, \u0432\u0435\u0447\u0435\u0440, \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b.  \u041c\u0430\u0441\u043a\u0438, \u043a\u043e\u0441\u0442\u044e\u043c\u044b, \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f  \u0432 \u043c\u043e\u043a\u0440\u043e\u0439 \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0435.", "description": "<p data-block-key=\"lhqto\">\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u2014 \u044d\u0442\u043e \u043c\u0430\u0433\u0438\u044f, \u0441\u043a\u0440\u044b\u0442\u0430\u044f \u0437\u0430 \u043c\u0430\u0441\u043a\u0430\u043c\u0438. \u041c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u0432 \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0447\u0430\u0441, \u043a\u043e\u0433\u0434\u0430 \u043c\u043e\u043a\u0440\u0430\u044f \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0430 \u043e\u0442\u0440\u0430\u0436\u0430\u0435\u0442 \u043e\u0433\u043d\u0438 \u0444\u043e\u043d\u0430\u0440\u0435\u0439, \u0430 \u043f\u043b\u043e\u0449\u0430\u0434\u044c \u0421\u0430\u043d-\u041c\u0430\u0440\u043a\u043e \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0442\u0435\u0430\u0442\u0440\u0430\u043b\u044c\u043d\u0443\u044e \u0441\u0446\u0435\u043d\u0443. \u0412 \u043a\u0430\u0434\u0440\u0435 \u2014 \u043f\u0430\u0440\u0430 \u0432 \u0441\u0432\u0435\u0442\u043b\u044b\u0445 \u043c\u0430\u0441\u043a\u0430\u0445 \u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043a\u043e\u0441\u0442\u044e\u043c\u0430\u0445. \u041c\u044b \u0445\u043e\u0442\u0435\u043b\u0438 \u043f\u0435\u0440\u0435\u0434\u0430\u0442\u044c \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0441\u043e\u0431\u044b\u0442\u0438\u0435, \u0430 \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0435: \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u043e\u0435, \u0447\u0443\u0442\u044c \u0442\u0430\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435, \u043e\u0447\u0435\u043d\u044c \u0432\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u043e\u0435.</p>", "gallery": "[{\"type\": \"image\", \"value\": 81, \"id\": \"66812f2c-7942-449a-9b74-8b09c6f2e167\"}, {\"type\": \"image\", \"value\": 80, \"id\": \"f49bb4dd-1718-4392-8d29-f994846444c9\"}, {\"type\": \"image\", \"value\": 79, \"id\": \"0573e7b4-ea64-40c6-a3e4-db22031f60f7\"}, {\"type\": \"image\", \"value\": 78, \"id\": \"862b0a6a-3ad8-4157-a528-3997c9f47799\"}, {\"type\": \"image\", \"value\": 77, \"id\": \"81a9a708-8bfc-4d6c-8f3c-0950d2b24be5\"}]", "wagtail_admin_comments": []}','13',58,1,'Венецианский карнавал. Ночь масок.');
