INSERT INTO wagtailcore_revision VALUES(39,'2026-04-19 07:12:37.088258',NULL,1,'{"pk": 16, "path": "00010002000100030001", "depth": 5, "numchild": 0, "translation_key": "6b3e0a30-2e3a-4fc3-a871-33b027e3d925", "locale": 1, "latest_revision": 39, "live": false, "has_unpublished_changes": true, "first_published_at": null, "last_published_at": null, "live_revision": null, "go_live_at": null, "expire_at": null, "expired": false, "locked": false, "locked_at": null, "locked_by": null, "title": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b: \u043c\u0430\u0433\u0438\u044f, \u0441\u043a\u0440\u044b\u0442\u0430\u044f \u0437\u0430 \u043c\u0430\u0441\u043a\u043e\u0439", "draft_title": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b: \u043c\u0430\u0433\u0438\u044f, \u0441\u043a\u0440\u044b\u0442\u0430\u044f \u0437\u0430 \u043c\u0430\u0441\u043a\u043e\u0439", "slug": "post-karnaval", "content_type": 55, "url_path": "/portfolio/photo_studio/blog_photo/post-karnaval/", "owner": 1, "seo_title": "", "show_in_menus": false, "search_description": "", "latest_revision_created_at": "2026-04-19T07:12:32.822Z", "alias_of": null, "date": "2026-02-10", "intro": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u2014 \u044d\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a, \u0430 \u043f\u043e\u0433\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u0432 \u0434\u0440\u0443\u0433\u0443\u044e \u044d\u043f\u043e\u0445\u0443. \u041c\u0430\u0441\u043a\u0438, \u043a\u043e\u0441\u0442\u044e\u043c\u044b, \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0441\u0432\u0435\u0442 \u0438 \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0432 \u043c\u043e\u043a\u0440\u043e\u0439 \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0435. \u041a\u0430\u043a \u043c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u044d\u0442\u043e \u0432\u043e\u043b\u0448\u0435\u0431\u0441\u0442\u0432\u043e.", "body": "<p data-block-key=\"yyb8a\">\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u2014 \u043e\u0434\u043d\u043e \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u0437\u0430\u0432\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u044e\u0449\u0438\u0445 \u0437\u0440\u0435\u043b\u0438\u0449 \u0432 \u043c\u0438\u0440\u0435. \u041c\u044b \u043f\u0440\u0438\u0435\u0445\u0430\u043b\u0438 \u0432 \u0412\u0435\u043d\u0435\u0446\u0438\u044e \u0432 \u0444\u0435\u0432\u0440\u0430\u043b\u0435, \u043a\u043e\u0433\u0434\u0430 \u0433\u043e\u0440\u043e\u0434 \u043d\u0430 \u0434\u0432\u0435 \u043d\u0435\u0434\u0435\u043b\u0438 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0442\u0435\u0430\u0442\u0440\u0430\u043b\u044c\u043d\u0443\u044e \u0441\u0446\u0435\u043d\u0443. \u041d\u0430\u0448\u0430 \u0437\u0430\u0434\u0430\u0447\u0430 \u0431\u044b\u043b\u0430 \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0437\u0430\u043f\u0435\u0447\u0430\u0442\u043b\u0435\u0442\u044c \u0441\u043e\u0431\u044b\u0442\u0438\u0435, \u0430 \u043f\u0435\u0440\u0435\u0434\u0430\u0442\u044c \u0435\u0433\u043e \u0430\u0442\u043c\u043e\u0441\u0444\u0435\u0440\u0443 \u2014 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u0443\u044e, \u0447\u0443\u0442\u044c \u0442\u0430\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e, \u043e\u0447\u0435\u043d\u044c \u0432\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0443\u044e.</p><p data-block-key=\"31hui\"></p><embed embedtype=\"image\" format=\"left\" id=\"78\" alt=\"\u043a\u043e\u0440\u043e\u0442\u043a1\"/><p data-block-key=\"bec0l\"></p><h4 data-block-key=\"2fsoh\"><b>\u0412\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0441\u0432\u0435\u0442</b></h4><p data-block-key=\"8p1sa\">\u041c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u0432 \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0447\u0430\u0441, \u043a\u043e\u0433\u0434\u0430 \u0441\u043e\u043b\u043d\u0446\u0435 \u0443\u0436\u0435 \u0441\u0430\u0434\u0438\u0442\u0441\u044f, \u0430 \u043d\u0430 \u043f\u043b\u043e\u0449\u0430\u0434\u0438 \u0421\u0430\u043d-\u041c\u0430\u0440\u043a\u043e \u0437\u0430\u0436\u0438\u0433\u0430\u044e\u0442\u0441\u044f \u0444\u043e\u043d\u0430\u0440\u0438. \u0412 \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u0441\u0432\u0435\u0442 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043c\u044f\u0433\u043a\u0438\u043c, \u0437\u043e\u043b\u043e\u0442\u0438\u0441\u0442\u044b\u043c, \u0430 \u0442\u0435\u043d\u0438 \u2014 \u0434\u043b\u0438\u043d\u043d\u044b\u043c\u0438 \u0438 \u0432\u044b\u0440\u0430\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438. \u0418\u043c\u0435\u043d\u043d\u043e \u0432 \u044d\u0442\u043e\u0442 \u043c\u043e\u043c\u0435\u043d\u0442 \u043c\u0430\u0441\u043a\u0438 \u0432\u044b\u0433\u043b\u044f\u0434\u044f\u0442 \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u0437\u0430\u0433\u0430\u0434\u043e\u0447\u043d\u043e, \u0430 \u043a\u043e\u0441\u0442\u044e\u043c\u044b \u2014 \u043e\u0431\u044a\u0451\u043c\u043d\u043e \u0438 \u0431\u043e\u0433\u0430\u0442\u043e.</p><h4 data-block-key=\"1nu07\"><b>\u041e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0432 \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0435</b></h4><p data-block-key=\"99d1s\">\u041f\u043e\u0441\u043b\u0435 \u0434\u043e\u0436\u0434\u044f \u043c\u043e\u043a\u0440\u0430\u044f \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0430 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u0435\u0440\u043a\u0430\u043b\u043e. \u041e\u0433\u043d\u0438 \u0444\u043e\u043d\u0430\u0440\u0435\u0439, \u0444\u0438\u0433\u0443\u0440\u044b \u0432 \u043c\u0430\u0441\u043a\u0430\u0445, \u043a\u043e\u043b\u043e\u043d\u043d\u044b \u0441\u043e\u0431\u043e\u0440\u0430 \u2014 \u0432\u0441\u0451 \u043e\u0442\u0440\u0430\u0436\u0430\u0435\u0442\u0441\u044f \u0432 \u043b\u0443\u0436\u0430\u0445, \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u0438\u043b\u043b\u044e\u0437\u0438\u044e \u0434\u0432\u043e\u0439\u043d\u043e\u0433\u043e \u043c\u0438\u0440\u0430. \u042d\u0442\u0438 \u043a\u0430\u0434\u0440\u044b \u0441\u0442\u0430\u043b\u0438 \u043e\u0434\u043d\u0438\u043c\u0438 \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u0430\u0442\u043c\u043e\u0441\u0444\u0435\u0440\u043d\u044b\u0445 \u0432 \u043d\u0430\u0448\u0435\u0439 \u0441\u0435\u0440\u0438\u0438.</p><p data-block-key=\"9dj56\"></p><h4 data-block-key=\"ishh\"><b>\u041f\u0430\u0440\u0430 \u0432 \u0441\u0432\u0435\u0442\u043b\u044b\u0445 \u043c\u0430\u0441\u043a\u0430\u0445</b></h4><p data-block-key=\"8uis8\">\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u043a\u0430\u0434\u0440 \u044d\u0442\u043e\u0439 \u0441\u044a\u0451\u043c\u043a\u0438 \u2014 \u043f\u0430\u0440\u0430 \u0432 \u0441\u0432\u0435\u0442\u043b\u044b\u0445 \u043c\u0430\u0441\u043a\u0430\u0445 \u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043a\u043e\u0441\u0442\u044e\u043c\u0430\u0445. \u041c\u044b \u0434\u043e\u043b\u0433\u043e \u0436\u0434\u0430\u043b\u0438 \u043c\u043e\u043c\u0435\u043d\u0442\u0430, \u043a\u043e\u0433\u0434\u0430 \u043e\u043d\u0438 \u043e\u043a\u0430\u0436\u0443\u0442\u0441\u044f \u0432 \u043d\u0443\u0436\u043d\u043e\u043c \u0441\u0432\u0435\u0442\u0435, \u043d\u0430 \u0444\u043e\u043d\u0435 \u0442\u0451\u043c\u043d\u043e\u0439 \u0430\u0440\u043a\u0438. \u0411\u0435\u043b\u044b\u0435 \u043c\u0430\u0441\u043a\u0438 \u043d\u0430 \u0438\u0445 \u043b\u0438\u0446\u0430\u0445 \u043f\u043e\u0434\u0447\u0451\u0440\u043a\u0438\u0432\u0430\u044e\u0442 \u0442\u0430\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0438 \u044d\u043b\u0435\u0433\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u044d\u0442\u043e\u0433\u043e \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0430.</p><h4 data-block-key=\"dapk8\"><b>\u0427\u0442\u043e \u0432 \u0438\u0442\u043e\u0433\u0435</b></h4><p data-block-key=\"b53hd\">\u041a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u0432 \u0412\u0435\u043d\u0435\u0446\u0438\u0438 \u2014 \u044d\u0442\u043e \u0431\u0435\u0441\u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0435 \u0432\u0434\u043e\u0445\u043d\u043e\u0432\u0435\u043d\u0438\u0435 \u0434\u043b\u044f \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0430. \u0417\u0434\u0435\u0441\u044c \u043a\u0430\u0436\u0434\u044b\u0439 \u043a\u0430\u0434\u0440 \u2014 \u0438\u0441\u0442\u043e\u0440\u0438\u044f. \u041c\u044b \u0432\u0435\u0440\u043d\u0443\u043b\u0438\u0441\u044c \u0441 \u0442\u044b\u0441\u044f\u0447\u0435\u0439 \u0441\u043d\u0438\u043c\u043a\u043e\u0432, \u043d\u043e \u0432 \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0432\u0437\u044f\u043b\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u0435, \u0433\u0434\u0435 \u0435\u0441\u0442\u044c \u0442\u0430 \u0441\u0430\u043c\u0430\u044f \u043c\u0430\u0433\u0438\u044f \u2014 \u0441\u0432\u0435\u0442, \u0442\u0435\u043d\u044c, \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u0438 \u0437\u0430\u0433\u0430\u0434\u043a\u0430.</p>", "post_image": 82, "wagtail_admin_comments": [], "tagged_items": [{"pk": 76, "tag": 2, "content_object": 16}, {"pk": 77, "tag": 6, "content_object": 16}, {"pk": 78, "tag": 3, "content_object": 16}, {"pk": 79, "tag": 4, "content_object": 16}, {"pk": 80, "tag": 5, "content_object": 16}], "gallery_images": [{"pk": 1, "sort_order": 0, "page": 16, "image": 81, "caption": ""}, {"pk": 2, "sort_order": 1, "page": 16, "image": 80, "caption": ""}, {"pk": 3, "sort_order": 2, "page": 16, "image": 79, "caption": ""}]}','16',55,1,'Венецианский карнавал: магия, скрытая за маской');
INSERT INTO wagtailcore_revision VALUES(40,'2026-04-19 07:12:48.537020',NULL,1,'{"pk": 16, "path": "00010002000100030001", "depth": 5, "numchild": 0, "translation_key": "6b3e0a30-2e3a-4fc3-a871-33b027e3d925", "locale": 1, "latest_revision": 39, "live": false, "has_unpublished_changes": true, "first_published_at": null, "last_published_at": null, "live_revision": null, "go_live_at": null, "expire_at": null, "expired": false, "locked": false, "locked_at": null, "locked_by": null, "title": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b: \u043c\u0430\u0433\u0438\u044f, \u0441\u043a\u0440\u044b\u0442\u0430\u044f \u0437\u0430 \u043c\u0430\u0441\u043a\u043e\u0439", "draft_title": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b: \u043c\u0430\u0433\u0438\u044f, \u0441\u043a\u0440\u044b\u0442\u0430\u044f \u0437\u0430 \u043c\u0430\u0441\u043a\u043e\u0439", "slug": "post-karnaval", "content_type": 55, "url_path": "/portfolio/photo_studio/blog_photo/post-karnaval/", "owner": 1, "seo_title": "", "show_in_menus": false, "search_description": "", "latest_revision_created_at": "2026-04-19T07:12:37.088Z", "alias_of": null, "date": "2026-02-10", "intro": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u2014 \u044d\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a, \u0430 \u043f\u043e\u0433\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u0432 \u0434\u0440\u0443\u0433\u0443\u044e \u044d\u043f\u043e\u0445\u0443. \u041c\u0430\u0441\u043a\u0438, \u043a\u043e\u0441\u0442\u044e\u043c\u044b, \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0441\u0432\u0435\u0442 \u0438 \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0432 \u043c\u043e\u043a\u0440\u043e\u0439 \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0435. \u041a\u0430\u043a \u043c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u044d\u0442\u043e \u0432\u043e\u043b\u0448\u0435\u0431\u0441\u0442\u0432\u043e.", "body": "<p data-block-key=\"yyb8a\">\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u2014 \u043e\u0434\u043d\u043e \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u0437\u0430\u0432\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u044e\u0449\u0438\u0445 \u0437\u0440\u0435\u043b\u0438\u0449 \u0432 \u043c\u0438\u0440\u0435. \u041c\u044b \u043f\u0440\u0438\u0435\u0445\u0430\u043b\u0438 \u0432 \u0412\u0435\u043d\u0435\u0446\u0438\u044e \u0432 \u0444\u0435\u0432\u0440\u0430\u043b\u0435, \u043a\u043e\u0433\u0434\u0430 \u0433\u043e\u0440\u043e\u0434 \u043d\u0430 \u0434\u0432\u0435 \u043d\u0435\u0434\u0435\u043b\u0438 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0442\u0435\u0430\u0442\u0440\u0430\u043b\u044c\u043d\u0443\u044e \u0441\u0446\u0435\u043d\u0443. \u041d\u0430\u0448\u0430 \u0437\u0430\u0434\u0430\u0447\u0430 \u0431\u044b\u043b\u0430 \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0437\u0430\u043f\u0435\u0447\u0430\u0442\u043b\u0435\u0442\u044c \u0441\u043e\u0431\u044b\u0442\u0438\u0435, \u0430 \u043f\u0435\u0440\u0435\u0434\u0430\u0442\u044c \u0435\u0433\u043e \u0430\u0442\u043c\u043e\u0441\u0444\u0435\u0440\u0443 \u2014 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u0443\u044e, \u0447\u0443\u0442\u044c \u0442\u0430\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e, \u043e\u0447\u0435\u043d\u044c \u0432\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0443\u044e.</p><p data-block-key=\"31hui\"></p><embed embedtype=\"image\" format=\"left\" id=\"78\" alt=\"\u043a\u043e\u0440\u043e\u0442\u043a1\"/><p data-block-key=\"bec0l\"></p><h4 data-block-key=\"2fsoh\"><b>\u0412\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0441\u0432\u0435\u0442</b></h4><p data-block-key=\"8p1sa\">\u041c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u0432 \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0447\u0430\u0441, \u043a\u043e\u0433\u0434\u0430 \u0441\u043e\u043b\u043d\u0446\u0435 \u0443\u0436\u0435 \u0441\u0430\u0434\u0438\u0442\u0441\u044f, \u0430 \u043d\u0430 \u043f\u043b\u043e\u0449\u0430\u0434\u0438 \u0421\u0430\u043d-\u041c\u0430\u0440\u043a\u043e \u0437\u0430\u0436\u0438\u0433\u0430\u044e\u0442\u0441\u044f \u0444\u043e\u043d\u0430\u0440\u0438. \u0412 \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u0441\u0432\u0435\u0442 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043c\u044f\u0433\u043a\u0438\u043c, \u0437\u043e\u043b\u043e\u0442\u0438\u0441\u0442\u044b\u043c, \u0430 \u0442\u0435\u043d\u0438 \u2014 \u0434\u043b\u0438\u043d\u043d\u044b\u043c\u0438 \u0438 \u0432\u044b\u0440\u0430\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438. \u0418\u043c\u0435\u043d\u043d\u043e \u0432 \u044d\u0442\u043e\u0442 \u043c\u043e\u043c\u0435\u043d\u0442 \u043c\u0430\u0441\u043a\u0438 \u0432\u044b\u0433\u043b\u044f\u0434\u044f\u0442 \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u0437\u0430\u0433\u0430\u0434\u043e\u0447\u043d\u043e, \u0430 \u043a\u043e\u0441\u0442\u044e\u043c\u044b \u2014 \u043e\u0431\u044a\u0451\u043c\u043d\u043e \u0438 \u0431\u043e\u0433\u0430\u0442\u043e.</p><h4 data-block-key=\"1nu07\"><b>\u041e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0432 \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0435</b></h4><p data-block-key=\"99d1s\">\u041f\u043e\u0441\u043b\u0435 \u0434\u043e\u0436\u0434\u044f \u043c\u043e\u043a\u0440\u0430\u044f \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0430 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u0435\u0440\u043a\u0430\u043b\u043e. \u041e\u0433\u043d\u0438 \u0444\u043e\u043d\u0430\u0440\u0435\u0439, \u0444\u0438\u0433\u0443\u0440\u044b \u0432 \u043c\u0430\u0441\u043a\u0430\u0445, \u043a\u043e\u043b\u043e\u043d\u043d\u044b \u0441\u043e\u0431\u043e\u0440\u0430 \u2014 \u0432\u0441\u0451 \u043e\u0442\u0440\u0430\u0436\u0430\u0435\u0442\u0441\u044f \u0432 \u043b\u0443\u0436\u0430\u0445, \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u0438\u043b\u043b\u044e\u0437\u0438\u044e \u0434\u0432\u043e\u0439\u043d\u043e\u0433\u043e \u043c\u0438\u0440\u0430. \u042d\u0442\u0438 \u043a\u0430\u0434\u0440\u044b \u0441\u0442\u0430\u043b\u0438 \u043e\u0434\u043d\u0438\u043c\u0438 \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u0430\u0442\u043c\u043e\u0441\u0444\u0435\u0440\u043d\u044b\u0445 \u0432 \u043d\u0430\u0448\u0435\u0439 \u0441\u0435\u0440\u0438\u0438.</p><p data-block-key=\"9dj56\"></p><embed embedtype=\"image\" format=\"right\" id=\"77\" alt=\"\u043a\u043e\u0440\u043e\u0442\u043a2\"/><p data-block-key=\"802ml\"></p><h4 data-block-key=\"ishh\"><b>\u041f\u0430\u0440\u0430 \u0432 \u0441\u0432\u0435\u0442\u043b\u044b\u0445 \u043c\u0430\u0441\u043a\u0430\u0445</b></h4><p data-block-key=\"8uis8\">\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u043a\u0430\u0434\u0440 \u044d\u0442\u043e\u0439 \u0441\u044a\u0451\u043c\u043a\u0438 \u2014 \u043f\u0430\u0440\u0430 \u0432 \u0441\u0432\u0435\u0442\u043b\u044b\u0445 \u043c\u0430\u0441\u043a\u0430\u0445 \u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043a\u043e\u0441\u0442\u044e\u043c\u0430\u0445. \u041c\u044b \u0434\u043e\u043b\u0433\u043e \u0436\u0434\u0430\u043b\u0438 \u043c\u043e\u043c\u0435\u043d\u0442\u0430, \u043a\u043e\u0433\u0434\u0430 \u043e\u043d\u0438 \u043e\u043a\u0430\u0436\u0443\u0442\u0441\u044f \u0432 \u043d\u0443\u0436\u043d\u043e\u043c \u0441\u0432\u0435\u0442\u0435, \u043d\u0430 \u0444\u043e\u043d\u0435 \u0442\u0451\u043c\u043d\u043e\u0439 \u0430\u0440\u043a\u0438. \u0411\u0435\u043b\u044b\u0435 \u043c\u0430\u0441\u043a\u0438 \u043d\u0430 \u0438\u0445 \u043b\u0438\u0446\u0430\u0445 \u043f\u043e\u0434\u0447\u0451\u0440\u043a\u0438\u0432\u0430\u044e\u0442 \u0442\u0430\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0438 \u044d\u043b\u0435\u0433\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u044d\u0442\u043e\u0433\u043e \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0430.</p><h4 data-block-key=\"dapk8\"><b>\u0427\u0442\u043e \u0432 \u0438\u0442\u043e\u0433\u0435</b></h4><p data-block-key=\"b53hd\">\u041a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u0432 \u0412\u0435\u043d\u0435\u0446\u0438\u0438 \u2014 \u044d\u0442\u043e \u0431\u0435\u0441\u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0435 \u0432\u0434\u043e\u0445\u043d\u043e\u0432\u0435\u043d\u0438\u0435 \u0434\u043b\u044f \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0430. \u0417\u0434\u0435\u0441\u044c \u043a\u0430\u0436\u0434\u044b\u0439 \u043a\u0430\u0434\u0440 \u2014 \u0438\u0441\u0442\u043e\u0440\u0438\u044f. \u041c\u044b \u0432\u0435\u0440\u043d\u0443\u043b\u0438\u0441\u044c \u0441 \u0442\u044b\u0441\u044f\u0447\u0435\u0439 \u0441\u043d\u0438\u043c\u043a\u043e\u0432, \u043d\u043e \u0432 \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0432\u0437\u044f\u043b\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u0435, \u0433\u0434\u0435 \u0435\u0441\u0442\u044c \u0442\u0430 \u0441\u0430\u043c\u0430\u044f \u043c\u0430\u0433\u0438\u044f \u2014 \u0441\u0432\u0435\u0442, \u0442\u0435\u043d\u044c, \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u0438 \u0437\u0430\u0433\u0430\u0434\u043a\u0430.</p>", "post_image": 82, "wagtail_admin_comments": [], "tagged_items": [{"pk": 81, "tag": 2, "content_object": 16}, {"pk": 82, "tag": 6, "content_object": 16}, {"pk": 83, "tag": 3, "content_object": 16}, {"pk": 84, "tag": 4, "content_object": 16}, {"pk": 85, "tag": 5, "content_object": 16}], "gallery_images": [{"pk": 1, "sort_order": 0, "page": 16, "image": 81, "caption": ""}, {"pk": 2, "sort_order": 1, "page": 16, "image": 80, "caption": ""}, {"pk": 3, "sort_order": 2, "page": 16, "image": 79, "caption": ""}]}','16',55,1,'Венецианский карнавал: магия, скрытая за маской');
INSERT INTO wagtailcore_revision VALUES(41,'2026-04-19 07:12:54.008163',NULL,1,'{"pk": 16, "path": "00010002000100030001", "depth": 5, "numchild": 0, "translation_key": "6b3e0a30-2e3a-4fc3-a871-33b027e3d925", "locale": 1, "latest_revision": 40, "live": false, "has_unpublished_changes": true, "first_published_at": null, "last_published_at": null, "live_revision": null, "go_live_at": null, "expire_at": null, "expired": false, "locked": false, "locked_at": null, "locked_by": null, "title": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b: \u043c\u0430\u0433\u0438\u044f, \u0441\u043a\u0440\u044b\u0442\u0430\u044f \u0437\u0430 \u043c\u0430\u0441\u043a\u043e\u0439", "draft_title": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b: \u043c\u0430\u0433\u0438\u044f, \u0441\u043a\u0440\u044b\u0442\u0430\u044f \u0437\u0430 \u043c\u0430\u0441\u043a\u043e\u0439", "slug": "post-karnaval", "content_type": 55, "url_path": "/portfolio/photo_studio/blog_photo/post-karnaval/", "owner": 1, "seo_title": "", "show_in_menus": false, "search_description": "", "latest_revision_created_at": "2026-04-19T07:12:48.537Z", "alias_of": null, "date": "2026-02-10", "intro": "\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u2014 \u044d\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a, \u0430 \u043f\u043e\u0433\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u0432 \u0434\u0440\u0443\u0433\u0443\u044e \u044d\u043f\u043e\u0445\u0443. \u041c\u0430\u0441\u043a\u0438, \u043a\u043e\u0441\u0442\u044e\u043c\u044b, \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0441\u0432\u0435\u0442 \u0438 \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0432 \u043c\u043e\u043a\u0440\u043e\u0439 \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0435. \u041a\u0430\u043a \u043c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u044d\u0442\u043e \u0432\u043e\u043b\u0448\u0435\u0431\u0441\u0442\u0432\u043e.", "body": "<p data-block-key=\"yyb8a\">\u0412\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u2014 \u043e\u0434\u043d\u043e \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u0437\u0430\u0432\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u044e\u0449\u0438\u0445 \u0437\u0440\u0435\u043b\u0438\u0449 \u0432 \u043c\u0438\u0440\u0435. \u041c\u044b \u043f\u0440\u0438\u0435\u0445\u0430\u043b\u0438 \u0432 \u0412\u0435\u043d\u0435\u0446\u0438\u044e \u0432 \u0444\u0435\u0432\u0440\u0430\u043b\u0435, \u043a\u043e\u0433\u0434\u0430 \u0433\u043e\u0440\u043e\u0434 \u043d\u0430 \u0434\u0432\u0435 \u043d\u0435\u0434\u0435\u043b\u0438 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0442\u0435\u0430\u0442\u0440\u0430\u043b\u044c\u043d\u0443\u044e \u0441\u0446\u0435\u043d\u0443. \u041d\u0430\u0448\u0430 \u0437\u0430\u0434\u0430\u0447\u0430 \u0431\u044b\u043b\u0430 \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0437\u0430\u043f\u0435\u0447\u0430\u0442\u043b\u0435\u0442\u044c \u0441\u043e\u0431\u044b\u0442\u0438\u0435, \u0430 \u043f\u0435\u0440\u0435\u0434\u0430\u0442\u044c \u0435\u0433\u043e \u0430\u0442\u043c\u043e\u0441\u0444\u0435\u0440\u0443 \u2014 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u0443\u044e, \u0447\u0443\u0442\u044c \u0442\u0430\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e, \u043e\u0447\u0435\u043d\u044c \u0432\u0435\u043d\u0435\u0446\u0438\u0430\u043d\u0441\u043a\u0443\u044e.</p><p data-block-key=\"31hui\"></p><embed embedtype=\"image\" format=\"left\" id=\"78\" alt=\"\u043a\u043e\u0440\u043e\u0442\u043a1\"/><p data-block-key=\"bec0l\"></p><h4 data-block-key=\"2fsoh\"><b>\u0412\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0441\u0432\u0435\u0442</b></h4><p data-block-key=\"8p1sa\">\u041c\u044b \u0441\u043d\u0438\u043c\u0430\u043b\u0438 \u0432 \u0432\u0435\u0447\u0435\u0440\u043d\u0438\u0439 \u0447\u0430\u0441, \u043a\u043e\u0433\u0434\u0430 \u0441\u043e\u043b\u043d\u0446\u0435 \u0443\u0436\u0435 \u0441\u0430\u0434\u0438\u0442\u0441\u044f, \u0430 \u043d\u0430 \u043f\u043b\u043e\u0449\u0430\u0434\u0438 \u0421\u0430\u043d-\u041c\u0430\u0440\u043a\u043e \u0437\u0430\u0436\u0438\u0433\u0430\u044e\u0442\u0441\u044f \u0444\u043e\u043d\u0430\u0440\u0438. \u0412 \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u0441\u0432\u0435\u0442 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043c\u044f\u0433\u043a\u0438\u043c, \u0437\u043e\u043b\u043e\u0442\u0438\u0441\u0442\u044b\u043c, \u0430 \u0442\u0435\u043d\u0438 \u2014 \u0434\u043b\u0438\u043d\u043d\u044b\u043c\u0438 \u0438 \u0432\u044b\u0440\u0430\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438. \u0418\u043c\u0435\u043d\u043d\u043e \u0432 \u044d\u0442\u043e\u0442 \u043c\u043e\u043c\u0435\u043d\u0442 \u043c\u0430\u0441\u043a\u0438 \u0432\u044b\u0433\u043b\u044f\u0434\u044f\u0442 \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u0437\u0430\u0433\u0430\u0434\u043e\u0447\u043d\u043e, \u0430 \u043a\u043e\u0441\u0442\u044e\u043c\u044b \u2014 \u043e\u0431\u044a\u0451\u043c\u043d\u043e \u0438 \u0431\u043e\u0433\u0430\u0442\u043e.</p><h4 data-block-key=\"1nu07\"><b>\u041e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0432 \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0435</b></h4><p data-block-key=\"99d1s\">\u041f\u043e\u0441\u043b\u0435 \u0434\u043e\u0436\u0434\u044f \u043c\u043e\u043a\u0440\u0430\u044f \u0431\u0440\u0443\u0441\u0447\u0430\u0442\u043a\u0430 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u0435\u0440\u043a\u0430\u043b\u043e. \u041e\u0433\u043d\u0438 \u0444\u043e\u043d\u0430\u0440\u0435\u0439, \u0444\u0438\u0433\u0443\u0440\u044b \u0432 \u043c\u0430\u0441\u043a\u0430\u0445, \u043a\u043e\u043b\u043e\u043d\u043d\u044b \u0441\u043e\u0431\u043e\u0440\u0430 \u2014 \u0432\u0441\u0451 \u043e\u0442\u0440\u0430\u0436\u0430\u0435\u0442\u0441\u044f \u0432 \u043b\u0443\u0436\u0430\u0445, \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u0438\u043b\u043b\u044e\u0437\u0438\u044e \u0434\u0432\u043e\u0439\u043d\u043e\u0433\u043e \u043c\u0438\u0440\u0430. \u042d\u0442\u0438 \u043a\u0430\u0434\u0440\u044b \u0441\u0442\u0430\u043b\u0438 \u043e\u0434\u043d\u0438\u043c\u0438 \u0438\u0437 \u0441\u0430\u043c\u044b\u0445 \u0430\u0442\u043c\u043e\u0441\u0444\u0435\u0440\u043d\u044b\u0445 \u0432 \u043d\u0430\u0448\u0435\u0439 \u0441\u0435\u0440\u0438\u0438.</p><p data-block-key=\"9dj56\"></p><embed embedtype=\"image\" format=\"right\" id=\"77\" alt=\"\u043a\u043e\u0440\u043e\u0442\u043a2\"/><p data-block-key=\"802ml\"></p><h4 data-block-key=\"ishh\"><b>\u041f\u0430\u0440\u0430 \u0432 \u0441\u0432\u0435\u0442\u043b\u044b\u0445 \u043c\u0430\u0441\u043a\u0430\u0445</b></h4><p data-block-key=\"8uis8\">\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u043a\u0430\u0434\u0440 \u044d\u0442\u043e\u0439 \u0441\u044a\u0451\u043c\u043a\u0438 \u2014 \u043f\u0430\u0440\u0430 \u0432 \u0441\u0432\u0435\u0442\u043b\u044b\u0445 \u043c\u0430\u0441\u043a\u0430\u0445 \u0438 \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043a\u043e\u0441\u0442\u044e\u043c\u0430\u0445. \u041c\u044b \u0434\u043e\u043b\u0433\u043e \u0436\u0434\u0430\u043b\u0438 \u043c\u043e\u043c\u0435\u043d\u0442\u0430, \u043a\u043e\u0433\u0434\u0430 \u043e\u043d\u0438 \u043e\u043a\u0430\u0436\u0443\u0442\u0441\u044f \u0432 \u043d\u0443\u0436\u043d\u043e\u043c \u0441\u0432\u0435\u0442\u0435, \u043d\u0430 \u0444\u043e\u043d\u0435 \u0442\u0451\u043c\u043d\u043e\u0439 \u0430\u0440\u043a\u0438. \u0411\u0435\u043b\u044b\u0435 \u043c\u0430\u0441\u043a\u0438 \u043d\u0430 \u0438\u0445 \u043b\u0438\u0446\u0430\u0445 \u043f\u043e\u0434\u0447\u0451\u0440\u043a\u0438\u0432\u0430\u044e\u0442 \u0442\u0430\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0438 \u044d\u043b\u0435\u0433\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u044d\u0442\u043e\u0433\u043e \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0430.</p><h4 data-block-key=\"dapk8\"><b>\u0427\u0442\u043e \u0432 \u0438\u0442\u043e\u0433\u0435</b></h4><p data-block-key=\"b53hd\">\u041a\u0430\u0440\u043d\u0430\u0432\u0430\u043b \u0432 \u0412\u0435\u043d\u0435\u0446\u0438\u0438 \u2014 \u044d\u0442\u043e \u0431\u0435\u0441\u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0435 \u0432\u0434\u043e\u0445\u043d\u043e\u0432\u0435\u043d\u0438\u0435 \u0434\u043b\u044f \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0430. \u0417\u0434\u0435\u0441\u044c \u043a\u0430\u0436\u0434\u044b\u0439 \u043a\u0430\u0434\u0440 \u2014 \u0438\u0441\u0442\u043e\u0440\u0438\u044f. \u041c\u044b \u0432\u0435\u0440\u043d\u0443\u043b\u0438\u0441\u044c \u0441 \u0442\u044b\u0441\u044f\u0447\u0435\u0439 \u0441\u043d\u0438\u043c\u043a\u043e\u0432, \u043d\u043e \u0432 \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0432\u0437\u044f\u043b\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u0435, \u0433\u0434\u0435 \u0435\u0441\u0442\u044c \u0442\u0430 \u0441\u0430\u043c\u0430\u044f \u043c\u0430\u0433\u0438\u044f \u2014 \u0441\u0432\u0435\u0442, \u0442\u0435\u043d\u044c, \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u0438 \u0437\u0430\u0433\u0430\u0434\u043a\u0430.</p>", "post_image": 82, "wagtail_admin_comments": [], "tagged_items": [{"pk": 86, "tag": 2, "content_object": 16}, {"pk": 87, "tag": 6, "content_object": 16}, {"pk": 88, "tag": 3, "content_object": 16}, {"pk": 89, "tag": 4, "content_object": 16}, {"pk": 90, "tag": 5, "content_object": 16}], "gallery_images": [{"pk": 1, "sort_order": 0, "page": 16, "image": 81, "caption": ""}, {"pk": 2, "sort_order": 1, "page": 16, "image": 80, "caption": ""}, {"pk": 3, "sort_order": 2, "page": 16, "image": 79, "caption": ""}]}','16',55,1,'Венецианский карнавал: магия, скрытая за маской');
