INSERT INTO wagtailcore_revision VALUES(547,'2026-05-24 10:56:43.266542',NULL,1,'{"pk": 29, "path": "0001000200070001", "depth": 4, "numchild": 0, "translation_key": "470f543a-a6f9-4eeb-b7fa-a2242d9ac9f3", "locale": 1, "latest_revision": 546, "live": true, "has_unpublished_changes": true, "first_published_at": "2026-05-09T16:49:22.672Z", "last_published_at": "2026-05-24T10:31:15.885Z", "live_revision": 539, "go_live_at": null, "expire_at": null, "expired": false, "locked": false, "locked_at": null, "locked_by": null, "title": "\u0413\u043e\u0442\u043e\u0432\u044b\u0439 \u0441\u0430\u0439\u0442 \u0434\u043b\u044f \u043a\u0430\u0444\u0435 \u043d\u0430 Wagtail", "draft_title": "\u0413\u043e\u0442\u043e\u0432\u044b\u0439 \u0441\u0430\u0439\u0442 \u0434\u043b\u044f \u043a\u0430\u0444\u0435 \u043d\u0430 Wagtail", "slug": "razrabotka-saita-kafe-wagtail", "content_type": 66, "url_path": "/portfolio/projects/razrabotka-saita-kafe-wagtail/", "owner": 1, "seo_title": "\u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u0441\u0430\u0439\u0442\u0430 \u043a\u0430\u0444\u0435, \u0441\u0430\u0439\u0442 \u0434\u043b\u044f \u043a\u0430\u0444\u0435 \u043d\u0430 wagtail, wagtail \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0430, \u0441\u0430\u0439\u0442 \u0440\u0435\u0441\u0442\u043e\u0440\u0430\u043d\u0430, \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043c\u0435\u043d\u044e \u0441\u0430\u0439\u0442, \u0431\u0440\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0441\u0442\u043e\u043b\u0438\u043a\u043e\u0432 \u043e\u043d\u043b\u0430\u0439\u043d, \u0432\u0435\u0431-\u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a wagtail, \u0430\u0434\u0430\u043f\u0442\u0438\u0432\u043d\u044b\u0439 \u0441\u0430\u0439\u0442 \u043a\u0430\u0444\u0435", "show_in_menus": false, "search_description": "\u0413\u043e\u0442\u043e\u0432\u044b\u0439 \u0441\u0430\u0439\u0442 \u0434\u043b\u044f \u043a\u0430\u0444\u0435 \u043d\u0430 Wagtail. \u0423\