INSERT INTO home_projectpage VALUES(30,'Портфолио, блог, управление проектами и заявками — всё в одном сайте на Wagtail','Python, Wagtail, PostgreSQL, HTML5, CSS3, JavaScript, адаптивная вёрстка, Django','2026-04-15','',152,4,NULL,1,'https://github.com/MariyaMakhina/blog-photo-studio',138,'[{"type": "content_block", "value": {"title": "\u0412 \u0447\u0451\u043c \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u044d\u0442\u043e\u0433\u043e \u0441\u0430\u0439\u0442\u0430?", "description": "<p data-block-key=\"wntxa\">\u0424\u043e\u0442\u043e\u0433\u0440\u0430\u0444 \u0438\u043b\u0438 \u0441\u0442\u0443\u0434\u0438\u044f \u0441\u0430\u043c\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0442 \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0438 \u0431\u043b\u043e\u0433\u043e\u043c \u0447\u0435\u0440\u0435\u0437 \u043f\u0430\u043d\u0435\u043b\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f Wagtail. \u041d\u043e\u0432\u0430\u044f \u0440\u0430\u0431\u043e\u0442\u0430 \u043f\u043e\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u0441\u0430\u0439\u0442\u0435 \u0437\u0430 2 \u043c\u0438\u043d\u0443\u0442\u044b. \u0421\u0442\u0430\u0442\u044c\u044f \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0435\u0442\u0441\u044f \u0437\u0430 3 \u043c\u0438\u043d\u0443\u0442\u044b. \u0417\u0430\u044f\u0432\u043a\u0438 \u043d\u0430 \u0441\u044a\u0451\u043c\u043a\u0443 \u043f\u0440\u0438\u0445\u043e\u0434\u044f\u0442 \u0441\u0440\u0430\u0437\u0443 \u0432 \u043f\u0430\u043d\u0435\u043b\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0438 \u043d\u0430 email. \u041f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0438\u0441\u0442 \u043d\u0435 \u043d\u0443\u0436\u0435\u043d \u2014 \u043d\u0438 \u0434\u043b\u044f \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0439, \u043d\u0438 \u0434\u043b\u044f \u043f\u0440\u0430\u0432\u043e\u043a.</p><p data-block-key=\"2i8as\"><b>\u0427\u0442\u043e \u0443\u043c\u0435\u0435\u0442 \u044d\u0442\u043e\u0442 \u0441\u0430\u0439\u0442:</b></p><ul><li data-block-key=\"1j4lh\">\u041f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0441 \u0444\u0438\u043b\u044c\u0442\u0440\u0430\u0446\u0438\u0435\u0439 \u043f\u043e \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f\u043c \u2014 \u043a\u043b\u0438\u0435\u043d\u0442\u044b \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442 \u043d\u0443\u0436\u043d\u043e\u0435</li><li data-block-key=\"b7jaf\">\u0411\u043b\u043e\u0433 \u0441\u043e \u0441\u0442\u0430\u0442\u044c\u044f\u043c\u0438 \u0438 \u0442\u0435\u0433\u0430\u043c\u0438 \u2014 \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 SEO \u0438 \u0434\u043e\u0432\u0435\u0440\u0438\u044e</li><li data-block-key=\"8jo1g\">\u0424\u043e\u0440\u043c\u0430 \u0437\u0430\u043a\u0430\u0437\u0430 \u0441\u044a\u0451\u043c\u043a\u0438 \u2014 \u0437\u0430\u044f\u0432\u043a\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f \u0438 \u043d\u0435 \u0442\u0435\u0440\u044f\u044e\u0442\u0441\u044f</li><li data-block-key=\"2d4so\">\u041a\u0430\u0440\u0442\u0430 \u0441 \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u043c \u0441\u0442\u0443\u0434\u0438\u0438 \u2014 \u043a\u043b\u0438\u0435\u043d\u0442\u044b \u0432\u0438\u0434\u044f\u0442, \u0433\u0434\u0435 \u0432\u044b \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0435\u0441\u044c</li><li data-block-key=\"ai0iu\">\u0410\u0434\u0430\u043f\u0442\u0438\u0432\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d \u2014 \u043d\u0430 \u043b\u044e\u0431\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435</li></ul><p data-block-key=\"a0jt4\"><b>\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442:</b> \u0441\u0430\u0439\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043a\u0430\u043a \u043f\u043e\u043b\u043d\u043e\u0446\u0435\u043d\u043d\u044b\u0439 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u043f\u0440\u043e\u0434\u0430\u0436, \u0430 \u043d\u0435 \u043a\u0430\u043a \u0441\u0442\u0430\u0442\u0438\u0447\u043d\u0430\u044f \u0432\u0438\u0437\u0438\u0442\u043a\u0430. \u0412\u044b \u0437\u0430\u043d\u0438\u043c\u0430\u0435\u0442\u0435\u0441\u044c \u0441\u044a\u0451\u043c\u043a\u0430\u043c\u0438, \u0430 \u043d\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u043c \u0441\u0430\u0439\u0442\u043e\u043c.</p><p data-block-key=\"b24hp\"><b>\u0410\u043a\u0446\u0438\u0438, \u0438\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438 \u0441 \u0441\u043e\u0446\u0441\u0435\u0442\u044f\u043c\u0438?</b> Wagtail \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0434 \u043b\u044e\u0431\u044b\u0435 \u0437\u0430\u0434\u0430\u0447\u0438 \u0431\u0438\u0437\u043d\u0435\u0441\u0430.</p>", "image": 173}, "id": "3f2c8571-6869-451c-b4fe-e83b18cfaa6f"}, {"type": "content_block", "value": {"title": "\u041f\u043e\u0447\u0435\u043c\u0443 \u044d\u0442\u043e\u0442 \u0441\u0430\u0439\u0442 \u043d\u0430 Wagtail.", "description": "<p data-block-key=\"5sucr\">Wagtail \u2014 \u043f\u0440\u043e\u0444\u0435\u0441\u0441\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430\u044f CMS (\u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0441\u0430\u0439\u0442\u043e\u043c). \u0412 \u043d\u0435\u0439 \u0435\u0441\u0442\u044c \u0432\u0441\u0451 \u0434\u043b\u044f \u0444\u043e\u0442\u043e\u0441\u0442\u0443\u0434\u0438\u0438: \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e, \u0431\u043b\u043e\u0433, \u0444\u043e\u0440\u043c\u044b \u0437\u0430\u044f\u0432\u043e\u043a, \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 SEO. \u0410\u0434\u043c\u0438\u043d\u043a\u0430 \u043f\u043e\u043d\u044f\u0442\u043d\u0430 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u0430\u043c. \u0412\u044b \u0432\u043b\u0430\u0434\u0435\u0435\u0442\u0435 \u0441\u0430\u0439\u0442\u043e\u043c \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u2014 \u043a\u043e\u0434 \u0438 \u0434\u0430\u043d\u043d\u044b\u0435 \u0432\u0430\u0448\u0438. \u041c\u043e\u0436\u043d\u043e \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0442\u044c \u043d\u043e\u0432\u044b\u0439 \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0430\u043b \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0434\u0435\u043b\u043e\u043a.</p>", "image": null}, "id": "58aa080f-a186-4faf-bd3f-e08a5e632131"}, {"type": "clear_float", "value": {"line_visible": true}, "id": "b83569ad-d2ed-4089-8ca4-dd6393c70afa"}, {"type": "content_block", "value": {"title": "\u041a\u0430\u043a \u0443\u0441\u0442\u0440\u043e\u0435\u043d\u043e \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435", "description": "", "image": null}, "id": "c2d56fa2-c366-49a4-8c0b-df3f6fcf4065"}, {"type": "content_with_icon", "value": {"title": "\u041f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0438 \u0431\u043b\u043e\u0433", "icon": "\ud83d\udccc", "icon_svg": 100, "text": "<p data-block-key=\"fn4ue\">\u0412 \u043f\u0430\u043d\u0435\u043b\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f Wagtail \u0432\u044b \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u0435 \u0438 \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e, \u0438 \u0431\u043b\u043e\u0433\u043e\u043c \u0432 \u043e\u0434\u043d\u043e\u043c \u043c\u0435\u0441\u0442\u0435.</p><p data-block-key=\"5h0sc\"><b>\u041f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e:</b> \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b \u2014 \u0444\u043e\u0442\u043e, \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435, \u0434\u0430\u0442\u0443, \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044e. \u041d\u0430 \u0441\u0430\u0439\u0442\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0444\u0438\u043b\u044c\u0442\u0440 \u043f\u043e \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f\u043c. \u041d\u043e\u0432\u0430\u044f \u0440\u0430\u0431\u043e\u0442\u0430 \u043f\u043e\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0437\u0430 2 \u043c\u0438\u043d\u0443\u0442\u044b.</p><p data-block-key=\"4qda5\"><b>\u0411\u043b\u043e\u0433:</b> \u043f\u0438\u0448\u0435\u0442\u0435 \u0441\u0442\u0430\u0442\u044c\u0438 \u0432 \u0443\u0434\u043e\u0431\u043d\u043e\u043c \u0440\u0435\u0434\u0430\u043a\u0442\u043e\u0440\u0435. \u0414\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0435 \u0442\u0435\u0433\u0438 \u2014 \u043e\u043d\u0438 \u043f\u043e\u043c\u043e\u0433\u0430\u044e\u0442 \u043f\u043e\u0438\u0441\u043a\u0443. \u041c\u043e\u0436\u043d\u043e \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0447\u0435\u0440\u043d\u043e\u0432\u0438\u043a \u0438\u043b\u0438 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u0442\u044c \u0441\u0440\u0430\u0437\u0443.</p><p data-block-key=\"4frl1\">\u041f\u0440\u0438 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0438 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0438\u043b\u0438 \u0441\u0442\u0430\u0442\u044c\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0441\u0440\u0430\u0437\u0443 \u0432\u0438\u0434\u0435\u043d \u0441\u043f\u0440\u0430\u0432\u0430 \u2014 \u0432 \u0440\u0435\u0436\u0438\u043c\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0430.</p><p data-block-key=\"cvhah\">\u0412\u0441\u0451 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u043e\u043c \u2014 \u0431\u0435\u0437 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0438\u0441\u0442\u0430, \u0431\u0435\u0437 \u043b\u0438\u0448\u043d\u0438\u0445 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0439.</p>", "media": [{"type": "gallery", "value": {"heading": "", "images": [{"type": "item", "value": {"image": 166, "caption": ""}, "id": "931ef88d-2a18-4253-9274-26081125a348"}, {"type": "item", "value": {"image": 167, "caption": ""}, "id": "c8439099-fbdf-4222-9261-d52a0aab2cd6"}, {"type": "item", "value": {"image": 168, "caption": ""}, "id": "e0d45182-de31-4593-b799-c0632b159a27"}, {"type": "item", "value": {"image": 169, "caption": ""}, "id": "1a4628ed-6824-4f04-8fef-73dcd7fbe4a6"}, {"type": "item", "value": {"image": 170, "caption": ""}, "id": "d6789b68-542b-4717-97f3-9491a7d19f7c"}, {"type": "item", "value": {"image": 171, "caption": ""}, "id": "645a5d8c-8589-47ac-bf25-da5a5ec6630d"}, {"type": "item", "value": {"image": 172, "caption": ""}, "id": "a3f776ea-a3f5-46b5-bdaa-f01d99c6314e"}]}, "id": "ab809afb-6c96-4d93-8521-66a4f9a84697"}], "image_position": "left", "image_width": "50"}, "id": "db76e6bf-7a32-4ae5-a9b3-ccb673baaf6f"}, {"type": "content_with_icon", "value": {"title": "\u0417\u0430\u044f\u0432\u043a\u0438 \u043d\u0430 \u0441\u044a\u0451\u043c\u043a\u0443", "icon": "\ud83d\udccc", "icon_svg": 139, "text": "<p data-block-key=\"mmdlh\">\u0424\u043e\u0440\u043c\u0430 \u0437\u0430\u043a\u0430\u0437\u0430 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u0432 \u043f\u0430\u043d\u0435\u043b\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f Wagtail. \u0412\u0441\u0435 \u0437\u0430\u044f\u0432\u043a\u0438 \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u0432 \u043e\u0434\u043d\u043e\u043c \u043c\u0435\u0441\u0442\u0435 \u2014 \u0432\u044b \u0432\u0438\u0434\u0438\u0442\u0435 \u0438\u043c\u044f, \u0442\u0435\u043b\u0435\u0444\u043e\u043d, \u0434\u0430\u0442\u0443 \u0438 \u043f\u043e\u0436\u0435\u043b\u0430\u043d\u0438\u044f \u043a\u043b\u0438\u0435\u043d\u0442\u0430. \u041f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0437\u0430\u044f\u0432\u043a\u0438 \u043c\u043e\u0436\u043d\u043e \u0434\u0443\u0431\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432 Telegram \u0438\u043b\u0438 \u043d\u0430 email.</p>", "media": [{"type": "single_image", "value": 141, "id": "8def245a-d55b-4e8e-ae3f-5ef8da55e868"}], "image_position": "right", "image_width": "50"}, "id": "fbdff5df-96e5-4028-a537-eaa3e1e1fc58"}, {"type": "content_with_icon", "value": {"title": "\u0412\u0441\u0451 \u043f\u043e\u0434 \u0432\u0430\u0448 \u0431\u0438\u0437\u043d\u0435\u0441", "icon": "\ud83d\udccc", "icon_svg": 102, "text": "<p data-block-key=\"jhosi\">\u0421\u0430\u0439\u0442 \u043d\u0435 \u0437\u0430\u0448\u0438\u0442 \u0432 \u0431\u0435\u0442\u043e\u043d\u0435. Wagtail \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0442\u044c \u043b\u044e\u0431\u044b\u0435 \u0444\u0443\u043d\u043a\u0446\u0438\u0438. \u0421\u0430\u0439\u0442 \u0440\u0430\u0441\u0442\u0451\u0442 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u0432\u0430\u0448\u0438\u043c \u0431\u0438\u0437\u043d\u0435\u0441\u043e\u043c. \u041d\u043e\u0432\u044b\u0435 \u0440\u0430\u0437\u0434\u0435\u043b\u044b, \u043d\u0435\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435 \u0431\u043b\u043e\u043a\u0438, \u0438\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438 \u2014 \u0432\u0441\u0451 \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u0442\u0441\u044f \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u044b\u0432\u0430\u043d\u0438\u044f \u0432\u0441\u0435\u0433\u043e \u043a\u043e\u0434\u0430.</p>", "media": [], "image_position": "left", "image_width": "60"}, "id": "3fe3b177-6f94-4bcb-a629-f4300cf7b0ff"}, {"type": "carousel_block", "value": {"title": "", "slides": [{"type": "item", "value": {"image": 144, "caption": ""}, "id": "b84c4716-a7d2-4b6f-8e74-789c7974d553"}, {"type": "item", "value": {"image": 145, "caption": ""}, "id": "53f2f185-5776-427d-884e-36a2156ed8a9"}, {"type": "item", "value": {"image": 146, "caption": ""}, "id": "df854ab8-8b39-4b50-aa62-00180b20072d"}, {"type": "item", "value": {"image": 148, "caption": ""}, "id": "725ed1bd-84b5-4c74-b1d0-6cf2bec0f14a"}, {"type": "item", "value": {"image": 147, "caption": ""}, "id": "e0c97fc4-5599-4a27-b703-61f883467fd6"}, {"type": "item", "value": {"image": 149, "caption": ""}, "id": "8371c5ed-96a5-4489-8bf